ALTER TABLE dificultad_hibridos MODIFY COLUMN descripcion varchar(300) NULL;
ALTER TABLE dificultad_basemark MODIFY COLUMN agrupar varchar(30) NULL;

DELETE FROM dificultad_hibridos WHERE version = '2627';
DELETE FROM dificultad_tre WHERE version = '2627';
DELETE FROM dificultad_basemark WHERE version = '2627';
DELETE FROM dificultad_acrobacias WHERE version = '2627';
DELETE FROM dificultad_acropair WHERE version = '2627';

